UPDATE utility_bills SET invoice_number=(SELECT invoice_number FROM gas WHERE gas.amount_cents=utility_bills.amount_cents), period_start=(SELECT period_start FROM gas WHERE gas.amount_cents=utility_bills.amount_cents), period_end=(SELECT period_end FROM gas WHERE gas.amount_cents=utility_bills.amount_cents), consumption=(SELECT consumption FROM gas WHERE gas.amount_cents=utility_bills.amount_cents), consumption_unit='Smc', meter_reading=(SELECT meter_reading FROM gas WHERE gas.amount_cents=utility_bills.amount_cents), notes='Storico Eni Plenitude importato da fattura PDF' WHERE service='Gas' AND invoice_number IS NULL AND amount_cents IN (SELECT amount_cents FROM gas);--> statement-breakpoint
