INSERT INTO movements (kind,description,category,amount_cents,person,common_account,date) SELECT 'Spesa','Gas · Eni Plenitude','Utenze',g.amount_cents,'Comune','BBVA Utenze',g.issued FROM gas g WHERE NOT EXISTS (SELECT 1 FROM utility_bills u WHERE u.invoice_number=g.invoice_number OR (u.service='Gas' AND u.amount_cents=g.amount_cents));--> statement-breakpoint
