INSERT INTO utility_bills (movement_id,provider,service,amount_cents,wallet,common_account,date,recurring,period_start,period_end,consumption,consumption_unit,meter_reading,invoice_number,notes) SELECT m.id,'Eni Plenitude','Gas',g.amount_cents,'BBVA Utenze','BBVA Utenze',g.issued,0,g.period_start,g.period_end,g.consumption,'Smc',g.meter_reading,g.invoice_number,'Storico Eni Plenitude importato da fattura PDF' FROM gas g JOIN movements m ON m.description='Gas · Eni Plenitude' AND m.amount_cents=g.amount_cents AND m.date=g.issued WHERE NOT EXISTS (SELECT 1 FROM utility_bills u WHERE u.invoice_number=g.invoice_number OR (u.service='Gas' AND u.amount_cents=g.amount_cents));--> statement-breakpoint
INSERT INTO common_account_transactions (account,direction,description,category,amount_cents,date,source_movement_id) SELECT 'BBVA Utenze','Spesa','Gas · Eni Plenitude','Utenze',u.amount_cents,u.date,u.movement_id FROM utility_bills u WHERE u.invoice_number IN ('2510880308','2518126105','2525973720','2532483958','2538836946','2543160801','2610522000','2618310326','2622592883','2629926195') AND NOT EXISTS (SELECT 1 FROM common_account_transactions c WHERE c.source_movement_id=u.movement_id);
